// Host half: 计量采集、持久化与 RPC（v13 唯一版本：缓存命中计入输入）
return {
  inject: ['timer'],
  apply(ctx) {
    const fs = ctx.get('fs')
    const sandboxPolicy = ctx.get('sandboxPolicy')
    let fileTarget = null
    let root = null
    let rootSource = null
    let dirty = false

    const state = {
      totalInput: 0,          // 输入（含缓存命中）
      totalCacheRead: 0,      // 其中缓存命中
      totalOutput: 0,
      peakRoundTokens: 0,
      peakRoundDate: null,
      longestRoundMs: 0,
      longestRoundDate: null,
      daily: {},              // 'YYYY-MM-DD' -> { input, cache, output }
    }
    const activeRounds = new Map()

    function dateKey(at) {
      const d = new Date(at)
      const m = String(d.getMonth() + 1).padStart(2, '0')
      const day = String(d.getDate()).padStart(2, '0')
      return d.getFullYear() + '-' + m + '-' + day
    }

    // 优先取活跃会话的工作区 cwd（可写），退回 sandboxPolicy 配置根
    function pickRoot() {
      try {
        const sessions = ctx.get('sessions')
        if (sessions) {
          for (const s of sessions.list()) {
            const cwd = s && s.header && s.header.cwd
            if (cwd) { rootSource = 'sessions'; return cwd }
          }
        }
      } catch (err) { /* ignore */ }
      try {
        const agents = ctx.get('agents')
        if (agents) {
          for (const a of agents.list()) {
            const cwd = a && a.session && a.session.header && a.session.header.cwd
            if (cwd) { rootSource = 'agents'; return cwd }
          }
        }
      } catch (err) { /* ignore */ }
      try {
        if (sandboxPolicy && sandboxPolicy.workspaceRoot) {
          rootSource = 'sandboxPolicy'
          return sandboxPolicy.workspaceRoot
        }
      } catch (err) { /* ignore */ }
      rootSource = null
      return null
    }

    async function ensureTarget(preferred) {
      if (fileTarget || !fs) return
      const r = preferred || pickRoot()
      if (!r) return
      try {
        root = r
        fileTarget = await fs.resolve('.dsh-token-meter.json', { cwd: r })
        await load()
      } catch (err) {
        fileTarget = null
        root = null
        console.error('[token-meter] resolve failed:', err && err.message ? err.message : err)
      }
    }

    async function load() {
      if (!fs || !fileTarget) return
      try {
        const info = await fs.stat(fileTarget)
        if (!info) return
        const text = await fs.readText(fileTarget)
        const parsed = JSON.parse(text)
        if (!parsed || typeof parsed !== 'object') return
        state.totalInput = Number(parsed.totalInput) || 0
        state.totalCacheRead = Number(parsed.totalCacheRead) || 0
        state.totalOutput = Number(parsed.totalOutput) || 0
        state.peakRoundTokens = Number(parsed.peakRoundTokens) || 0
        state.peakRoundDate = parsed.peakRoundDate || null
        state.longestRoundMs = Number(parsed.longestRoundMs) || 0
        state.longestRoundDate = parsed.longestRoundDate || null
        state.daily = {}
        if (parsed.daily && typeof parsed.daily === 'object') {
          for (const [k, v] of Object.entries(parsed.daily)) {
            if (v && typeof v === 'object') {
              state.daily[k] = {
                input: Number(v.input) || 0,
                cache: Number(v.cache) || 0,
                output: Number(v.output) || 0,
              }
            }
          }
        }
        prune()
      } catch (err) {
        console.error('[token-meter] load failed:', err && err.message ? err.message : err)
      }
    }

    async function save() {
      if (!fs || !fileTarget || !root) return
      try {
        await fs.writeText(fileTarget, JSON.stringify(state), undefined, undefined, {
          mode: 'workspace-write',
          workspaceRoot: root,
        })
        dirty = false
      } catch (err) {
        console.error('[token-meter] save failed:', err && err.message ? err.message : err)
      }
    }

    function prune() {
      const cut = dateKey(Date.now() - 400 * 86400000)
      for (const k of Object.keys(state.daily)) {
        if (k < cut) delete state.daily[k]
      }
    }

    const scheduleSave = ctx.debounce(() => { save() }, 1500)

    function recordUsage(sessionId, usage, at) {
      // 输入包含缓存命中（prompt_tokens = inputTokens + cacheReadTokens）
      const input = (Number(usage.inputTokens) || 0) + (Number(usage.cacheReadTokens) || 0)
      const cache = Number(usage.cacheReadTokens) || 0
      const output = Number(usage.outputTokens) || 0
      if (input + output <= 0) return
      state.totalInput += input
      state.totalCacheRead += cache
      state.totalOutput += output
      const key = dateKey(at)
      const entry = state.daily[key] || (state.daily[key] = { input: 0, cache: 0, output: 0 })
      entry.input += input
      entry.cache += cache
      entry.output += output
      if (sessionId) {
        const round = activeRounds.get(sessionId)
        if (round) round.tokens += input + output
      }
      dirty = true
      if (!fileTarget) ensureTarget()
      scheduleSave()
    }

    // ---- 1. 包装每次流式模型调用，捕获 usage chunk ----
    ctx.on('llm/stream', (options, next) => {
      const inner = next()
      let usage = null
      async function* wrapped() {
        try {
          for await (const chunk of inner) {
            if (chunk && chunk.type === 'usage' && chunk.usage) usage = chunk.usage
            yield chunk
          }
        } finally {
          if (usage) {
            recordUsage(options.sessionId, usage, Date.now())
          }
        }
      }
      return wrapped()
    })

    // ---- 2. 轮次起点：用户消息被领取 ----
    ctx.on('agent/inbox/claimed', (payload) => {
      const id = payload.agent.id
      const cur = activeRounds.get(id)
      if (!cur || cur.turn !== payload.turn) {
        activeRounds.set(id, { turn: payload.turn, startedAt: Date.now(), tokens: 0 })
      }
    })

    // ---- 3. 轮次终点：更新最长时长与单轮峰值 ----
    ctx.on('agent/turn-stopping', (payload) => {
      const id = payload.agent.id
      const round = activeRounds.get(id)
      if (round && round.turn === payload.turn) {
        const now = Date.now()
        const dur = now - round.startedAt
        if (dur > state.longestRoundMs) {
          state.longestRoundMs = dur
          state.longestRoundDate = dateKey(now)
        }
        if (round.tokens > state.peakRoundTokens) {
          state.peakRoundTokens = round.tokens
          state.peakRoundDate = dateKey(now)
        }
        activeRounds.delete(id)
        dirty = true
        scheduleSave()
      }
    })

    // agent 出现后补解析可写根目录
    ctx.on('agent/created', (payload) => {
      const cwd = payload && payload.agent && payload.agent.session && payload.agent.session.header && payload.agent.session.header.cwd
      if (cwd) ensureTarget(cwd)
    })

    // ---- 4. 心跳：有变更时才落盘（保证异常退出不丢数据） ----
    ctx.interval(() => {
      if (dirty) {
        save()
      } else if (!fileTarget) {
        ensureTarget()
      }
    }, 10000)

    // ---- 5. Client RPC ----
    function buildState() {
      const today = dateKey(Date.now())
      const t = state.daily[today]
      const mk = (input, cache, output) => ({
        input,
        cacheRead: cache,
        output,
        total: input + output,
      })
      return {
        cumulative: mk(state.totalInput, state.totalCacheRead, state.totalOutput),
        today: mk(t ? t.input : 0, t ? t.cache : 0, t ? t.output : 0),
        peakRoundTokens: state.peakRoundTokens,
        peakRoundDate: state.peakRoundDate,
        longestRoundMs: state.longestRoundMs,
        longestRoundDate: state.longestRoundDate,
        daily: state.daily,
        generatedAt: Date.now(),
      }
    }

    harness.handle('meter:state', () => buildState())
    harness.handle('meter:diag', () => ({
      root,
      rootSource,
      fileTargetReady: !!fileTarget,
      totalInput: state.totalInput,
      totalCacheRead: state.totalCacheRead,
      totalOutput: state.totalOutput,
      dailyDays: Object.keys(state.daily).length,
      activeRounds: activeRounds.size,
      dirty,
      now: Date.now(),
    }))
    harness.handle('meter:reset', () => {
      state.totalInput = 0
      state.totalCacheRead = 0
      state.totalOutput = 0
      state.peakRoundTokens = 0
      state.peakRoundDate = null
      state.longestRoundMs = 0
      state.longestRoundDate = null
      state.daily = {}
      activeRounds.clear()
      dirty = true
      save()
      return buildState()
    })

    // 启动时解析根目录；停止时冲刷待写数据
    ctx.effect(() => {
      ensureTarget()
      return () => {
        scheduleSave.dispose()
        if (dirty) save()
      }
    })
  },
}

packages.client:
// Client half: 设置侧边栏「Token 计量」页面 + GitHub 风格热力图（v13 唯一版本）
return {
  inject: ['timer'],
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return

    // ---------- 包内样式 ----------
    styles.insert(`
.tm-page{display:flex;flex-direction:column;gap:16px;padding:4px 2px 24px;width:100%;box-sizing:border-box}
.tm-page-head{display:flex;align-items:center;justify-content:space-between;gap:12px}
.tm-page-title{font-size:16px;font-weight:600;color:var(--dsw-alias-label-primary)}
.tm-btn{padding:4px 12px;font-size:12px;line-height:20px;border-radius:6px;border:1px solid var(--dsw-alias-border-l2);background:var(--dsw-alias-bg-layer-1);color:var(--dsw-alias-label-primary);cursor:pointer;font-family:inherit}
.tm-btn:hover{border-color:var(--dsw-alias-brand-primary)}
.tm-btn-danger{color:var(--dsw-alias-state-error-primary);border-color:var(--dsw-alias-state-error-primary)}
.tm-reset{display:flex;align-items:center;gap:8px}
.tm-reset-ask{font-size:12px;color:var(--dsw-alias-state-warn-primary)}
.tm-loading{color:var(--dsw-alias-label-secondary);font-size:13px;padding:24px 0;text-align:center}
.tm-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
.tm-stat{background:var(--dsw-alias-bg-layer-1);border:1px solid var(--dsw-alias-border-l1);border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;gap:4px;min-width:0}
.tm-stat-label{font-size:12px;color:var(--dsw-alias-label-secondary)}
.tm-stat-value{font-size:20px;font-weight:700;color:var(--dsw-alias-label-primary);font-variant-numeric:tabular-nums;white-space:nowrap}
.tm-stat-sub{font-size:11px;color:var(--dsw-alias-label-secondary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tm-heat{background:var(--dsw-alias-bg-layer-1);border:1px solid var(--dsw-alias-border-l1);border-radius:10px;padding:14px;display:flex;flex-direction:column;gap:8px;overflow-x:auto;box-sizing:border-box}
.tm-heat-title{font-size:12px;color:var(--dsw-alias-label-secondary)}
.tm-heat *{box-sizing:border-box}
.tm-heat-months{display:flex;gap:2px;padding-left:16px;height:14px}
.tm-heat-month{width:9px;height:14px;font-size:10px;line-height:14px;color:var(--dsw-alias-label-secondary);white-space:nowrap;overflow:visible;position:relative}
.tm-heat-body{display:flex;gap:4px}
.tm-heat-gutter{width:12px;display:grid;grid-template-rows:repeat(7,9px);gap:2px}
.tm-heat-weekday{font-size:9px;line-height:9px;color:var(--dsw-alias-label-secondary);align-self:center}
.tm-heat-cols{display:flex;gap:2px}
.tm-heat-col{display:grid;grid-template-rows:repeat(7,9px);gap:2px}
.tm-cell{width:9px;height:9px;border-radius:2px;background:var(--dsw-alias-bg-layer-2);border:1px solid var(--dsw-alias-border-l1)}
.tm-cell:hover{border-color:var(--dsw-alias-label-secondary)}
.tm-l1{background:color-mix(in srgb,var(--dsw-alias-state-success-primary) 22%,var(--dsw-alias-bg-layer-1));border-color:transparent}
.tm-l2{background:color-mix(in srgb,var(--dsw-alias-state-success-primary) 42%,var(--dsw-alias-bg-layer-1));border-color:transparent}
.tm-l3{background:color-mix(in srgb,var(--dsw-alias-state-success-primary) 65%,var(--dsw-alias-bg-layer-1));border-color:transparent}
.tm-l4{background:var(--dsw-alias-state-success-primary);border-color:transparent}
.tm-heat-legend{display:flex;align-items:center;gap:3px;justify-content:flex-end;font-size:10px;color:var(--dsw-alias-label-secondary)}
/* 设置侧边栏导航：自定义图标替换默认齿轮 */
.tm-nav-label{display:inline-flex;align-items:center;gap:8px;min-width:0}
.tm-nav-label svg{flex:none}
button:has(.tm-nav-label)>svg{display:none}
`)

    // ---------- 设置侧边栏专用图标（柱状图） ----------
    function MeterIcon() {
      return React.createElement('svg', {
        width: 16,
        height: 16,
        viewBox: '0 0 16 16',
        fill: 'none',
        'aria-hidden': 'true',
      },
        React.createElement('rect', { x: 2, y: 8, width: 3, height: 6, rx: 1, fill: 'currentColor' }),
        React.createElement('rect', { x: 6.5, y: 4, width: 3, height: 10, rx: 1, fill: 'currentColor' }),
        React.createElement('rect', { x: 11, y: 1, width: 3, height: 13, rx: 1, fill: 'currentColor' }),
      )
    }

    // ---------- 工具函数 ----------
    function dateKeyOf(d) {
      const m = String(d.getMonth() + 1).padStart(2, '0')
      const day = String(d.getDate()).padStart(2, '0')
      return d.getFullYear() + '-' + m + '-' + day
    }

    function fmtNum(n) {
      if (n >= 100000000) return (n / 100000000).toFixed(2) + ' 亿'
      if (n >= 10000) return (n / 10000).toFixed(1) + ' 万'
      return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',')
    }

    function fmtDur(ms) {
      if (!ms) return '—'
      const s = Math.floor(ms / 1000)
      if (s < 60) return s + ' 秒'
      const m = Math.floor(s / 60)
      if (m < 60) return m + ' 分 ' + (s % 60) + ' 秒'
      const h = Math.floor(m / 60)
      return h + ' 小时 ' + (m % 60) + ' 分'
    }

    // ---------- 热力图：近 52 周，按周分列（周日起），最新在右侧 ----------
    function buildWeeks(daily) {
      const today = new Date()
      const lastDay = new Date(today)
      lastDay.setDate(today.getDate() + (6 - today.getDay()))
      const start = new Date(lastDay)
      start.setDate(lastDay.getDate() - (52 * 7 - 1))
      const weeks = []
      for (let w = 0; w < 52; w++) {
        const col = []
        for (let d = 0; d < 7; d++) {
          const day = new Date(start)
          day.setDate(start.getDate() + w * 7 + d)
          const key = dateKeyOf(day)
          const v = daily ? daily[key] : null
          col.push({ key, date: day, total: v ? (Number(v.input) || 0) + (Number(v.output) || 0) : 0 })
        }
        weeks.push(col)
      }
      return weeks
    }

    function levelOf(total, max) {
      if (!total) return 0
      if (max <= 0) return 1
      const r = Math.sqrt(total / max)
      if (r >= 0.75) return 4
      if (r >= 0.5) return 3
      if (r >= 0.25) return 2
      return 1
    }

    // ---------- 组件 ----------
    function StatCard(props) {
      return React.createElement('div', { className: 'tm-stat' },
        React.createElement('div', { className: 'tm-stat-label' }, props.label),
        React.createElement('div', { className: 'tm-stat-value' }, props.value),
        props.sub ? React.createElement('div', { className: 'tm-stat-sub' }, props.sub) : null,
      )
    }

    function Heatmap(props) {
      const daily = props.daily || {}
      const scrollRef = React.useRef(null)
      const didInit = React.useRef(false)
      // 默认滚到最右侧，直接看到最新记录（仅首次，避免刷新时抢走手动滚动位置）
      React.useEffect(() => {
        if (didInit.current) return
        didInit.current = true
        const el = scrollRef.current
        if (el) el.scrollLeft = el.scrollWidth
      }, [])

      const weeks = React.useMemo(() => buildWeeks(daily), [daily])
      const max = React.useMemo(() => {
        let m = 0
        for (const col of weeks) for (const c of col) if (c.total > m) m = c.total
        return m
      }, [weeks])
      const monthLabels = React.useMemo(() => {
        const out = []
        weeks.forEach((col, i) => {
          const hit = col.find((c) => c.date.getDate() === 1)
          if (hit) out.push({ index: i, label: (hit.date.getMonth() + 1) + '月' })
        })
        return out
      }, [weeks])

      const monthRow = React.createElement('div', { className: 'tm-heat-months' },
        weeks.map((col, i) => {
          const ml = monthLabels.find((x) => x.index === i)
          return React.createElement('div', { key: i, className: 'tm-heat-month' + (ml ? ' has' : '') }, ml ? ml.label : '')
        }),
      )

      const body = React.createElement('div', { className: 'tm-heat-body' },
        React.createElement('div', { className: 'tm-heat-gutter' },
          [1, 3, 5].map((r) =>
            React.createElement('div', { key: r, className: 'tm-heat-weekday', style: { gridRow: r + 1 } },
              ['', '一', '', '三', '', '五', ''][r],
            )),
        ),
        React.createElement('div', { className: 'tm-heat-cols' },
          weeks.map((col, w) =>
            React.createElement('div', { key: w, className: 'tm-heat-col' },
              col.map((c) => {
                const lv = levelOf(c.total, max)
                const title = c.key + ' · ' + c.total.toLocaleString() + ' tokens'
                return React.createElement('div', {
                  key: c.key,
                  className: 'tm-cell' + (lv ? ' tm-l' + lv : ''),
                  title,
                })
              }),
            )),
        ),
      )

      const legend = React.createElement('div', { className: 'tm-heat-legend' },
        React.createElement('span', null, '少'),
        [0, 1, 2, 3, 4].map((l) => React.createElement('div', { key: l, className: 'tm-cell' + (l ? ' tm-l' + l : '') })),
        React.createElement('span', null, '多'),
      )

      return React.createElement('div', { className: 'tm-heat', ref: scrollRef },
        React.createElement('div', { className: 'tm-heat-title' }, '每日 Token 用量（近 52 周）'),
        monthRow,
        body,
        legend,
      )
    }

    function TokenMeterPage() {
      const [data, setData] = React.useState(null)
      const [confirming, setConfirming] = React.useState(false)
      const load = React.useCallback(() => {
        host.call('meter:state')
          .then((res) => { if (res) setData(res) })
          .catch(() => {})
      }, [])
      React.useEffect(() => {
        load()
        return ctx.interval(load, 3000)
      }, [load])
      const reset = React.useCallback(() => {
        host.call('meter:reset')
          .then((res) => { if (res) setData(res); setConfirming(false) })
          .catch(() => { setConfirming(false) })
      }, [])

      const cum = data ? data.cumulative : null
      const today = data ? data.today : null

      return React.createElement('div', { className: 'tm-page' },
        React.createElement('div', { className: 'tm-page-head' },
          React.createElement('div', { className: 'tm-page-title' }, 'Token 计量'),
          confirming
            ? React.createElement('div', { className: 'tm-reset' },
                React.createElement('span', { className: 'tm-reset-ask' }, '确认清空全部数据？'),
                React.createElement('button', { className: 'tm-btn tm-btn-danger', onClick: reset }, '确认'),
                React.createElement('button', { className: 'tm-btn', onClick: () => setConfirming(false) }, '取消'),
              )
            : React.createElement('button', { className: 'tm-btn', onClick: () => setConfirming(true) }, '清空数据'),
        ),
        data === null
          ? React.createElement('div', { className: 'tm-loading' }, '加载中…')
          : React.createElement(React.Fragment, null,
              React.createElement('div', { className: 'tm-stats' },
                React.createElement(StatCard, {
                  label: '累计 Token',
                  value: fmtNum(cum.total),
                  sub: '输入 ' + fmtNum(cum.input) + ' · 输出 ' + fmtNum(cum.output) + ' · 缓存 ' + fmtNum(cum.cacheRead),
                }),
                React.createElement(StatCard, {
                  label: '今日 Token',
                  value: fmtNum(today.total),
                  sub: '输入 ' + fmtNum(today.input) + ' · 输出 ' + fmtNum(today.output) + ' · 缓存 ' + fmtNum(today.cacheRead),
                }),
                React.createElement(StatCard, {
                  label: '单轮峰值 Token',
                  value: fmtNum(data.peakRoundTokens),
                  sub: data.peakRoundDate ? data.peakRoundDate + ' 达成' : '暂无记录',
                }),
                React.createElement(StatCard, {
                  label: '最长单次任务',
                  value: fmtDur(data.longestRoundMs),
                  sub: data.longestRoundDate ? data.longestRoundDate + ' 达成' : '暂无记录',
                }),
              ),
              React.createElement(Heatmap, { daily: data.daily }),
            ),
      )
    }

    // ---------- 注册设置侧边栏入口（自定义柱状图图标） ----------
    slots.inject('settings.section', () => slots.register(
      {
        name: 'settings.section',
        id: 'token-meter',
        order: 30,
        label: () => React.createElement('span', { className: 'tm-nav-label' },
          React.createElement(MeterIcon),
          'Token 计量',
        ),
      },
      () => React.createElement(TokenMeterPage),
    ))
  },
}

packages.host:
// ============================================================================
// Token Meter 计量插件 — Host 半区源码
// 插件 ID: tkmtr-2   Package: pkg-14
// 说明: 这是 cordis_define 的 code.host 函数体。把它作为 code.host 传入即可。
// 功能: 包装 llm/stream 瀑布捕获每次模型调用的 usage chunk，
//       输入 token 含缓存命中（prompt_tokens = inputTokens + cacheReadTokens），
//       用 agent/inbox/claimed → agent/turn-stopping 配对统计每轮峰值与时长，
//       数据持久化到会话工作区 .dsh-token-meter.json（重启不丢失）。
// ============================================================================
return {
  inject: ['timer'],
  apply(ctx) {
    const fs = ctx.get('fs')
    const sandboxPolicy = ctx.get('sandboxPolicy')
    let fileTarget = null
    let root = null
    let rootSource = null
    let dirty = false

    const state = {
      totalInput: 0,          // 输入（含缓存命中）
      totalCacheRead: 0,      // 其中缓存命中
      totalOutput: 0,
      peakRoundTokens: 0,
      peakRoundDate: null,
      longestRoundMs: 0,
      longestRoundDate: null,
      daily: {},              // 'YYYY-MM-DD' -> { input, cache, output }
    }
    const activeRounds = new Map()

    function dateKey(at) {
      const d = new Date(at)
      const m = String(d.getMonth() + 1).padStart(2, '0')
      const day = String(d.getDate()).padStart(2, '0')
      return d.getFullYear() + '-' + m + '-' + day
    }

    // 收集所有候选可写根：活跃会话 cwd（去重，新会话优先）+ 沙箱策略根（实例稳定）
    function collectRoots() {
      const roots = []
      const seen = new Set()
      const push = (r) => {
        if (r && !seen.has(r)) { seen.add(r); roots.push(r) }
      }
      try {
        const sessions = ctx.get('sessions')
        if (sessions) {
          const all = sessions.list()
          for (let i = all.length - 1; i >= 0; i--) {
            const cwd = all[i] && all[i].header && all[i].header.cwd
            if (cwd) push(cwd)
          }
        }
      } catch (err) { /* ignore */ }
      try {
        const agents = ctx.get('agents')
        if (agents) {
          const all = agents.list()
          for (let i = all.length - 1; i >= 0; i--) {
            const cwd = all[i] && all[i].session && all[i].session.header && all[i].session.header.cwd
            if (cwd) push(cwd)
          }
        }
      } catch (err) { /* ignore */ }
      try {
        if (sandboxPolicy && sandboxPolicy.workspaceRoot) push(sandboxPolicy.workspaceRoot)
      } catch (err) { /* ignore */ }
      return roots
    }

    // 1) 找出所有已有数据文件（新会话优先排在前面）
    async function findExistingTarget() {
      if (!fs) return []
      const files = []
      for (const r of collectRoots()) {
        try {
          const t = await fs.resolve('.dsh-token-meter.json', { cwd: r })
          const info = await fs.stat(t)
          if (info) files.push({ root: r, fileTarget: t })
        } catch (err) { /* 该根下无数据文件，继续找 */ }
      }
      return files
    }

    // 从另一份数据文件吸收增量：两份同源累计（同一插件实例），
    // 各项取最大值即为正确合并（迁移/续接场景不丢数据）
    async function absorbFrom(other) {
      if (!fs) return
      try {
        const text = await fs.readText(other.fileTarget)
        const p = JSON.parse(text)
        if (!p || typeof p !== 'object') return
        const num = (v) => Number(v) || 0
        state.totalInput = Math.max(state.totalInput, num(p.totalInput))
        state.totalCacheRead = Math.max(state.totalCacheRead, num(p.totalCacheRead))
        state.totalOutput = Math.max(state.totalOutput, num(p.totalOutput))
        if (num(p.peakRoundTokens) > state.peakRoundTokens) {
          state.peakRoundTokens = num(p.peakRoundTokens)
          state.peakRoundDate = p.peakRoundDate || null
        }
        if (num(p.longestRoundMs) > state.longestRoundMs) {
          state.longestRoundMs = num(p.longestRoundMs)
          state.longestRoundDate = p.longestRoundDate || null
        }
        if (p.daily && typeof p.daily === 'object') {
          for (const [k, v] of Object.entries(p.daily)) {
            if (!v || typeof v !== 'object') continue
            const cur = state.daily[k] || (state.daily[k] = { input: 0, cache: 0, output: 0 })
            cur.input = Math.max(cur.input, num(v.input))
            cur.cache = Math.max(cur.cache, num(v.cache))
            cur.output = Math.max(cur.output, num(v.output))
          }
        }
        dirty = true
        console.log('[token-meter] absorbed data from', other.root)
      } catch (err) {
        console.error('[token-meter] absorb failed:', err && err.message ? err.message : err)
      }
    }

    // 2) 退回：优先实例稳定的沙箱策略根（= dsh 启动目录，重启不变），
    //    再退回活跃会话的工作区 cwd
    function pickRoot() {
      try {
        if (sandboxPolicy && sandboxPolicy.workspaceRoot) {
          rootSource = 'sandboxPolicy'
          return sandboxPolicy.workspaceRoot
        }
      } catch (err) { /* ignore */ }
      try {
        const sessions = ctx.get('sessions')
        if (sessions) {
          for (const s of sessions.list()) {
            const cwd = s && s.header && s.header.cwd
            if (cwd) { rootSource = 'sessions'; return cwd }
          }
        }
      } catch (err) { /* ignore */ }
      try {
        const agents = ctx.get('agents')
        if (agents) {
          for (const a of agents.list()) {
            const cwd = a && a.session && a.session.header && a.session.header.cwd
            if (cwd) { rootSource = 'agents'; return cwd }
          }
        }
      } catch (err) { /* ignore */ }
      rootSource = null
      return null
    }

    async function ensureTarget(preferred) {
      if (fileTarget || !fs) return
      // 1) 已有数据文件 → 主用第一个（新会话优先），其余文件只吸收增量后弃用
      const files = await findExistingTarget()
      if (files.length > 0) {
        root = files[0].root
        rootSource = 'existing-data'
        fileTarget = files[0].fileTarget
        await load()
        for (let i = 1; i < files.length; i++) {
          await absorbFrom(files[i])
        }
        if (dirty) scheduleSave()
        return
      }
      // 2) 否则取稳定根
      const r = preferred || pickRoot()
      if (!r) return
      try {
        root = r
        fileTarget = await fs.resolve('.dsh-token-meter.json', { cwd: r })
        await load()
      } catch (err) {
        fileTarget = null
        root = null
        console.error('[token-meter] resolve failed:', err && err.message ? err.message : err)
      }
    }

    async function load() {
      if (!fs || !fileTarget) return
      try {
        const info = await fs.stat(fileTarget)
        if (!info) return
        const text = await fs.readText(fileTarget)
        const parsed = JSON.parse(text)
        if (!parsed || typeof parsed !== 'object') return
        state.totalInput = Number(parsed.totalInput) || 0
        state.totalCacheRead = Number(parsed.totalCacheRead) || 0
        state.totalOutput = Number(parsed.totalOutput) || 0
        state.peakRoundTokens = Number(parsed.peakRoundTokens) || 0
        state.peakRoundDate = parsed.peakRoundDate || null
        state.longestRoundMs = Number(parsed.longestRoundMs) || 0
        state.longestRoundDate = parsed.longestRoundDate || null
        state.daily = {}
        if (parsed.daily && typeof parsed.daily === 'object') {
          for (const [k, v] of Object.entries(parsed.daily)) {
            if (v && typeof v === 'object') {
              state.daily[k] = {
                input: Number(v.input) || 0,
                cache: Number(v.cache) || 0,
                output: Number(v.output) || 0,
              }
            }
          }
        }
        prune()
      } catch (err) {
        console.error('[token-meter] load failed:', err && err.message ? err.message : err)
      }
    }

    async function save() {
      if (!fs || !fileTarget || !root) return
      try {
        await fs.writeText(fileTarget, JSON.stringify(state), undefined, undefined, {
          mode: 'workspace-write',
          workspaceRoot: root,
        })
        dirty = false
      } catch (err) {
        console.error('[token-meter] save failed:', err && err.message ? err.message : err)
      }
    }

    function prune() {
      const cut = dateKey(Date.now() - 400 * 86400000)
      for (const k of Object.keys(state.daily)) {
        if (k < cut) delete state.daily[k]
      }
    }

    const scheduleSave = ctx.debounce(() => { save() }, 1500)

    function recordUsage(sessionId, usage, at) {
      // 输入包含缓存命中（prompt_tokens = inputTokens + cacheReadTokens）
      const input = (Number(usage.inputTokens) || 0) + (Number(usage.cacheReadTokens) || 0)
      const cache = Number(usage.cacheReadTokens) || 0
      const output = Number(usage.outputTokens) || 0
      if (input + output <= 0) return
      state.totalInput += input
      state.totalCacheRead += cache
      state.totalOutput += output
      const key = dateKey(at)
      const entry = state.daily[key] || (state.daily[key] = { input: 0, cache: 0, output: 0 })
      entry.input += input
      entry.cache += cache
      entry.output += output
      if (sessionId) {
        const round = activeRounds.get(sessionId)
        if (round) round.tokens += input + output
      }
      dirty = true
      if (!fileTarget) ensureTarget()
      scheduleSave()
    }

    // ---- 1. 包装每次流式模型调用，捕获 usage chunk ----
    ctx.on('llm/stream', (options, next) => {
      const inner = next()
      let usage = null
      async function* wrapped() {
        try {
          for await (const chunk of inner) {
            if (chunk && chunk.type === 'usage' && chunk.usage) usage = chunk.usage
            yield chunk
          }
        } finally {
          if (usage) {
            recordUsage(options.sessionId, usage, Date.now())
          }
        }
      }
      return wrapped()
    })

    // ---- 2. 轮次起点：用户消息被领取 ----
    ctx.on('agent/inbox/claimed', (payload) => {
      const id = payload.agent.id
      const cur = activeRounds.get(id)
      if (!cur || cur.turn !== payload.turn) {
        activeRounds.set(id, { turn: payload.turn, startedAt: Date.now(), tokens: 0 })
      }
    })

    // ---- 3. 轮次终点：更新最长时长与单轮峰值 ----
    ctx.on('agent/turn-stopping', (payload) => {
      const id = payload.agent.id
      const round = activeRounds.get(id)
      if (round && round.turn === payload.turn) {
        const now = Date.now()
        const dur = now - round.startedAt
        if (dur > state.longestRoundMs) {
          state.longestRoundMs = dur
          state.longestRoundDate = dateKey(now)
        }
        if (round.tokens > state.peakRoundTokens) {
          state.peakRoundTokens = round.tokens
          state.peakRoundDate = dateKey(now)
        }
        activeRounds.delete(id)
        dirty = true
        scheduleSave()
      }
    })

    // agent 出现后补解析可写根目录
    ctx.on('agent/created', (payload) => {
      const cwd = payload && payload.agent && payload.agent.session && payload.agent.session.header && payload.agent.session.header.cwd
      if (cwd) ensureTarget(cwd)
    })

    // ---- 4. 心跳：有变更时才落盘（保证异常退出不丢数据） ----
    ctx.interval(() => {
      if (dirty) {
        save()
      } else if (!fileTarget) {
        ensureTarget()
      }
    }, 10000)

    // ---- 5. Client RPC ----
    function buildState() {
      const today = dateKey(Date.now())
      const t = state.daily[today]
      const mk = (input, cache, output) => ({
        input,
        cacheRead: cache,
        output,
        total: input + output,
      })
      return {
        cumulative: mk(state.totalInput, state.totalCacheRead, state.totalOutput),
        today: mk(t ? t.input : 0, t ? t.cache : 0, t ? t.output : 0),
        peakRoundTokens: state.peakRoundTokens,
        peakRoundDate: state.peakRoundDate,
        longestRoundMs: state.longestRoundMs,
        longestRoundDate: state.longestRoundDate,
        daily: state.daily,
        generatedAt: Date.now(),
      }
    }

    harness.handle('meter:state', () => buildState())
    harness.handle('meter:diag', () => ({
      root,
      rootSource,
      fileTargetReady: !!fileTarget,
      totalInput: state.totalInput,
      totalCacheRead: state.totalCacheRead,
      totalOutput: state.totalOutput,
      dailyDays: Object.keys(state.daily).length,
      activeRounds: activeRounds.size,
      dirty,
      now: Date.now(),
    }))
    harness.handle('meter:reset', () => {
      state.totalInput = 0
      state.totalCacheRead = 0
      state.totalOutput = 0
      state.peakRoundTokens = 0
      state.peakRoundDate = null
      state.longestRoundMs = 0
      state.longestRoundDate = null
      state.daily = {}
      activeRounds.clear()
      dirty = true
      save()
      return buildState()
    })

    // 启动时解析根目录；停止时冲刷待写数据
    ctx.effect(() => {
      ensureTarget()
      return () => {
        scheduleSave.dispose()
        if (dirty) save()
      }
    })
  },
}

