return {
  apply(ctx) {
    const fs = ctx.get('fs')
    const shell = ctx.get('shell')
    const sandboxPolicy = ctx.get('sandboxPolicy')

    let root = null
    let rootSource = null

    // ---------- 工作区根目录解析（与 TokenMeter 同一套策略） ----------
    function pickRoot() {
      try {
        const sessions = ctx.get('sessions')
        if (sessions) {
          for (const s of sessions.list()) {
            const cwd = s && s.header && s.header.cwd
            if (cwd) { rootSource = 'sessions'; return cwd }
          }
        }
      } catch (err) { /* ignore */ }
      try {
        const agents = ctx.get('agents')
        if (agents) {
          for (const a of agents.list()) {
            const cwd = a && a.session && a.session.header && a.session.header.cwd
            if (cwd) { rootSource = 'agents'; return cwd }
          }
        }
      } catch (err) { /* ignore */ }
      try {
        if (sandboxPolicy && sandboxPolicy.workspaceRoot) {
          rootSource = 'sandboxPolicy'
          return sandboxPolicy.workspaceRoot
        }
      } catch (err) { /* ignore */ }
      rootSource = null
      return null
    }

    async function ensureRoot() {
      if (root) return root
      const r = pickRoot()
      if (r) root = r
      return root
    }

    function policy() {
      return { mode: 'workspace-write', workspaceRoot: root }
    }

    // 目录名校验：只允许安全的名称，防路径穿越
    const NAME_RE = /^[A-Za-z0-9_.-]+$/

    function shellQuote(s) {
      return "'" + String(s).replace(/'/g, "'\\''") + "'"
    }

    function errMsg(err) {
      return err && err.message ? err.message : String(err)
    }

    async function readLines(target, max) {
      try {
        const text = await fs.readText(target)
        return text.split('\n').slice(0, max)
      } catch (err) {
        return []
      }
    }

    async function exists(target) {
      try {
        const info = await fs.stat(target)
        return !!info
      } catch (err) {
        return false
      }
    }

    // ---------- 元信息提取 ----------
    function parseName(readmeLines) {
      for (const line of readmeLines) {
        const t = line.trim()
        if (!t) continue
        if (t.startsWith('#')) {
          const title = t.replace(/^#+\s*/, '').trim()
          if (title) return title
        }
        break
      }
      return ''
    }

    function parseDesc(readmeLines, hostLines, clientLines) {
      // README：标题后的第一段非空正文
      let collecting = false
      for (const line of readmeLines) {
        const t = line.trim()
        if (!t) { if (collecting) break; continue }
        if (t.startsWith('#')) { collecting = true; continue }
        if (collecting) return t.slice(0, 160)
      }
      // 代码头注释：// 功能: xxx
      for (const lines of [hostLines, clientLines]) {
        for (const line of lines.slice(0, 25)) {
          const m = line.match(/\/\/\s*(?:功能|描述)[:：]\s*(.+)/)
          if (m && m[1].trim()) return m[1].trim().slice(0, 160)
        }
      }
      return ''
    }

    async function trashInfo() {
      try {
        const trashTarget = await fs.resolve('.plugin-trash', { cwd: root })
        const info = await fs.stat(trashTarget)
        if (!info || info.type !== 'directory') return { exists: false, count: 0 }
        const entries = await fs.listDir(trashTarget)
        return { exists: true, count: entries.length }
      } catch (err) {
        return { exists: false, count: 0 }
      }
    }

    async function runShell(command) {
      if (!shell) return { ok: false, error: 'shell 服务不可用，无法执行文件操作' }
      try {
        const spec = shell.resolve({
          command,
          workdir: root,
          timeoutMs: 20000,
          sandboxPolicy: policy(),
        })
        const res = await shell.run(spec)
        if (res && res.exitCode === 0) return { ok: true }
        return { ok: false, error: '命令执行失败（exit ' + (res && res.exitCode !== null && res.exitCode !== undefined ? res.exitCode : '?') + '）' }
      } catch (err) {
        return { ok: false, error: '命令执行异常：' + errMsg(err) }
      }
    }

    // ---------- 核心：扫描目录里的插件 ----------
    async function listPlugins() {
      const r = await ensureRoot()
      if (!r) return { ok: false, error: '未找到可写的工作区根目录', root: null, rootSource: null, plugins: [], trash: null }
      try {
        const rootTarget = await fs.resolve('.', { cwd: r })
        const entries = await fs.listDir(rootTarget)
        const plugins = []
        for (const e of entries) {
          if (e.type !== 'directory') continue
          if (e.name.startsWith('.')) continue
          const dirPath = fs.processPath(e.target)
          let hasHost = false
          let hasClient = false
          let hostLines = []
          let clientLines = []
          let readmeLines = []
          try {
            const sub = await fs.listDir(e.target)
            for (const f of sub) {
              if (f.type !== 'file') continue
              if (f.name === 'host.js') { hasHost = true; hostLines = await readLines(f.target, 30) }
              else if (f.name === 'client.js') { hasClient = true; clientLines = await readLines(f.target, 30) }
              else if (f.name === 'README.md') { readmeLines = await readLines(f.target, 40) }
            }
          } catch (err) { /* 忽略不可读目录 */ }
          if (!hasHost && !hasClient) continue
          let disabled = false
          try {
            const markerTarget = await fs.resolve('.disabled', { cwd: dirPath })
            disabled = await exists(markerTarget)
          } catch (err) { /* ignore */ }
          plugins.push({
            name: parseName(readmeLines) || e.name,
            dir: e.name,
            hasHost,
            hasClient,
            hasReadme: readmeLines.length > 0,
            description: parseDesc(readmeLines, hostLines, clientLines),
            disabled,
          })
        }
        plugins.sort((a, b) => String(a.name).localeCompare(String(b.name), 'zh-Hans-CN'))
        const trash = await trashInfo()
        return { ok: true, root: r, rootSource, plugins, trash }
      } catch (err) {
        return { ok: false, error: '扫描失败：' + errMsg(err), root: r, rootSource, plugins: [], trash: null }
      }
    }

    // 校验 name 并返回插件目录 target；不是插件目录则返回 null
    async function findPluginDir(name) {
      const r = await ensureRoot()
      if (!r || !fs) return null
      if (!NAME_RE.test(String(name))) return null
      try {
        const target = await fs.resolve(String(name), { cwd: r })
        const info = await fs.stat(target)
        if (!info || info.type !== 'directory') return null
        const sub = await fs.listDir(target)
        let hasHost = false
        let hasClient = false
        for (const f of sub) {
          if (f.type !== 'file') continue
          if (f.name === 'host.js') hasHost = true
          else if (f.name === 'client.js') hasClient = true
        }
        return hasHost || hasClient ? target : null
      } catch (err) {
        return null
      }
    }

    // ---------- RPC ----------
    harness.handle('pcenter:list', () => listPlugins())

    harness.handle('pcenter:toggle', async (args) => {
      const name = args && args.name
      const enabled = !!(args && args.enabled)
      const target = await findPluginDir(name)
      if (!target) return { ok: false, error: '未找到插件目录：' + name }
      const dirPath = fs.processPath(target)
      if (enabled) {
        // 启用：删除 .disabled 标记
        return runShell('rm -f -- ' + shellQuote(dirPath + '/.disabled'))
      }
      // 禁用：写入 .disabled 标记文件
      if (!fs) return { ok: false, error: 'fs 服务不可用' }
      try {
        const markerTarget = await fs.resolve('.disabled', { cwd: dirPath })
        await fs.writeText(
          markerTarget,
          '# 该插件已被「插件中心」标记为禁用（Plugin Center disabled marker）\n',
          undefined,
          undefined,
          policy(),
        )
        return { ok: true }
      } catch (err) {
        return { ok: false, error: '写入禁用标记失败：' + errMsg(err) }
      }
    })

    harness.handle('pcenter:delete', async (args) => {
      const name = args && args.name
      const r = await ensureRoot()
      const target = await findPluginDir(name)
      if (!target) return { ok: false, error: '未找到插件目录：' + name }
      if (!r) return { ok: false, error: '未找到工作区根目录' }
      const dirPath = fs.processPath(target)
      const trashDir = r + '/.plugin-trash'
      const dest = trashDir + '/' + String(name) + '__' + Date.now()
      return runShell('mkdir -p -- ' + shellQuote(trashDir) + ' && mv -- ' + shellQuote(dirPath) + ' ' + shellQuote(dest))
    })

    harness.handle('pcenter:emptyTrash', async () => {
      const r = await ensureRoot()
      if (!r) return { ok: false, error: '未找到工作区根目录' }
      const trashDir = r + '/.plugin-trash'
      return runShell('rm -rf -- ' + shellQuote(trashDir) + ' && mkdir -p -- ' + shellQuote(trashDir))
    })

    harness.handle('pcenter:diag', async () => {
      const r = await ensureRoot()
      return { root: r, rootSource, fsReady: !!fs, shellReady: !!shell }
    })
  },
}

