        React.createElement('rect', { x: 1.5, y: 9, width: 5.5, height: 5.5, rx: 1, fill: 'currentColor', opacity: 0.5 }),
        React.createElement('rect', { x: 9, y: 9, width: 5.5, height: 5.5, rx: 1, fill: 'currentColor' }),
