        id: 'better-manager',
        order: 40,
        label: () => React.createElement('span', { className: 'bm-nav-label' },
          React.createElement(BlocksIcon),
          'Better Manager',
        ),
      },
      (props) => React.createElement(BetterManagerPage, { useSessions: props && props.useSessions }),
    ))
  },
