    // 卸载时显式 dispose 两个隐藏注册（disposer 幂等，重复调用无副作用）。
    ctx.effect(() => {
      setFooterHidden(true)
      setSettingsHidden(false)
      return () => {
        if (footerDisposer) { footerDisposer(); footerDisposer = null }
        if (settingsDisposer) { settingsDisposer(); settingsDisposer = null }
